import { mapCacheEvent, mapCacheSize } from "../observability.js";

/** Only generated bytes are cached; selection and response metadata stay fresh. */
export class MapOutputCache {
  private readonly entries = new Map<
    string,
    { data: Buffer; expiresAt: number }
  >();
  private readonly pending = new Map<string, Promise<Buffer>>();
  private bytes = 0;

  constructor(
    private readonly maxBytes: number,
    private readonly maxEntries: number,
  ) {}

  public async get(
    key: string,
    generate: () => Promise<Buffer>,
    isCurrent: () => boolean,
    maxAge: (data: Buffer) => number = () => Infinity,
  ): Promise<Buffer> {
    if (this.maxBytes === 0 || this.maxEntries === 0) return generate();
    const cached = this.entries.get(key);
    if (cached && cached.expiresAt <= Date.now()) {
      this.entries.delete(key);
      this.bytes -= cached.data.length;
      mapCacheSize(this.bytes, this.entries.size);
    }
    if (cached && cached.expiresAt > Date.now()) {
      this.entries.delete(key);
      this.entries.set(key, cached);
      mapCacheEvent("hit");
      return cached.data;
    }
    const pending = this.pending.get(key);
    if (pending) {
      mapCacheEvent("coalesced");
      return pending;
    }
    mapCacheEvent("miss");
    const generation = Promise.resolve()
      .then(generate)
      .then((data) => {
        // A baseline mutation may have overlapped generation. Its callers retry,
        // and the obsolete result must never become a reusable cache entry.
        if (isCurrent() && data.length <= this.maxBytes) {
          while (
            this.entries.size >= this.maxEntries ||
            this.bytes + data.length > this.maxBytes
          ) {
            const oldest = this.entries.keys().next().value;
            if (oldest === undefined) break;
            const evicted = this.entries.get(oldest);
            if (evicted) this.bytes -= evicted.data.length;
            this.entries.delete(oldest);
            mapCacheEvent("eviction");
          }
          this.entries.set(key, { data, expiresAt: Date.now() + maxAge(data) });
          this.bytes += data.length;
          mapCacheSize(this.bytes, this.entries.size);
        }
        return data;
      });
    this.pending.set(key, generation);
    try {
      return await generation;
    } finally {
      this.pending.delete(key);
    }
  }
}
